import{_ as t,o,c as a,a2 as r}from"./chunks/framework.ChIlRNAd.js";const g=JSON.parse('{"title":"Mail","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/mails.md","filePath":"en/guide/mails.md"}'),s={name:"en/guide/mails.md"};function n(d,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="mail" tabindex="-1">Mail <a class="header-anchor" href="#mail" aria-label="Permalink to &quot;Mail&quot;">​</a></h1><p>The <strong>Mail</strong> page (<code>/mails</code>) lists the Gmail mails of the active account. This is where you search, select and act in bulk, with an undo window for reversible actions.</p><hr><h2 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h2><ul><li><strong>Mail</strong> title and estimated number of results (&quot;~N results&quot;, an estimate from Gmail).</li><li><strong>Refresh</strong>: reloads the list.</li><li><strong>Save all to the NAS</strong>: saves every result of the current search to the <a href="./archives.html">Archives</a> (only mails not archived yet are copied).</li><li><strong>Create a rule</strong> (when a search is entered): opens the <a href="./rules.html#create-a-rule">rule</a> form; if the search is a single <code>from:address</code>, the sender is prefilled.</li></ul><hr><h2 id="account-one-account-or-all-accounts" tabindex="-1">Account: one account or &quot;All accounts&quot; <a class="header-anchor" href="#account-one-account-or-all-accounts" aria-label="Permalink to &quot;Account: one account or &quot;All accounts&quot;&quot;">​</a></h2><p>When at least two Gmail accounts are connected, a <strong>Gmail Account</strong> selector appears above the list. It offers each account and <strong>All accounts</strong> (address <code>/mails?account=all</code>, which replaces the former unified inbox).</p><p>In <strong>All accounts</strong> mode:</p><ul><li>an <strong>Account</strong> column shows which account each mail belongs to;</li><li>actions on a selection are sent account by account;</li><li><strong>Create a rule</strong> is only offered when the selection comes from a single account;</li><li><strong>Add a label</strong>, <strong>Save all to the NAS</strong>, selecting all results and the <strong>Show more</strong> button are not available.</li></ul><hr><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p>The search bar accepts Gmail syntax: keywords and operators (<code>from:</code>, <code>has:attachment</code>, <code>larger:10M</code>, <code>older_than:1y</code>…). When you press <code>Enter</code>, each operator becomes a <strong>token</strong> you remove with one click; the rest stays as free text.</p><h3 id="quick-searches-and-saved-searches" tabindex="-1">Quick searches and saved searches <a class="header-anchor" href="#quick-searches-and-saved-searches" aria-label="Permalink to &quot;Quick searches and saved searches&quot;">​</a></h3><p>Above the bar, chips apply a search in one click:</p><table tabindex="0"><thead><tr><th>Chip</th><th>Gmail query</th></tr></thead><tbody><tr><td>All</td><td><em>(empty)</em></td></tr><tr><td>Unread</td><td><code>is:unread</code></td></tr><tr><td>With attachments</td><td><code>has:attachment</code></td></tr><tr><td>Large &gt; 10 MB</td><td><code>larger:10m</code></td></tr><tr><td>Promotions &gt; 6 months</td><td><code>category:promotions older_than:6m</code></td></tr><tr><td>Social</td><td><code>category:social</code></td></tr><tr><td>Older than a year</td><td><code>older_than:1y</code></td></tr><tr><td>Spam</td><td><code>in:spam</code></td></tr><tr><td>Trash</td><td><code>in:trash</code></td></tr></tbody></table><p>Your <strong>saved searches</strong> follow. To create one, run a search then click <strong>Save search</strong> (the button shows when the search matches no chip); the chip is named after the query text.</p><p>The search and the account are part of the page address (<code>?q=…&amp;account=…</code>): a bookmark or the back button keeps them.</p><hr><h2 id="the-list" tabindex="-1">The list <a class="header-anchor" href="#the-list" aria-label="Permalink to &quot;The list&quot;">​</a></h2><p>Columns: <strong>From</strong>, <strong>Subject</strong> (with snippet, paperclip if there is an attachment), <strong>Labels</strong>, <strong>Size</strong>, <strong>Date</strong>. The <strong>Columns</strong> button hides or shows columns. Unread mails are in bold.</p><p>The list loads by pages: <strong>Show more</strong> loads the next one, until &quot;All mail loaded&quot;.</p><p>Each row&#39;s <code>⋯</code> menu offers <strong>Open</strong>, <strong>Archive (remove from inbox)</strong>, <strong>Save to the NAS</strong> and <strong>Delete</strong>.</p><p>On mobile, each mail is a card (sender, date, subject) with a checkbox.</p><hr><h2 id="select" tabindex="-1">Select <a class="header-anchor" href="#select" aria-label="Permalink to &quot;Select&quot;">​</a></h2><ul><li>Tick rows, or the header checkbox for the whole loaded page.</li><li><strong>All results</strong>: when a search is entered and every loaded row is ticked, a banner reads &quot;All N emails on this page are selected&quot; with the link <strong>Select all ~N search results</strong>. The action then applies to the whole query on the server, including mails not loaded; the counter shows &quot;~N selected&quot;.</li><li><strong>Clear selection</strong> (✕) or <code>Esc</code> empties the selection. Changing the search or the account empties it too.</li></ul><h3 id="action-bar" tabindex="-1">Action bar <a class="header-anchor" href="#action-bar" aria-label="Permalink to &quot;Action bar&quot;">​</a></h3><p>As soon as a mail is selected, the action bar appears:</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Archive (remove from inbox)</strong></td><td>removes the mails from the Gmail inbox</td></tr><tr><td><strong>Save to the NAS</strong></td><td>copies the mails to the <a href="./archives.html">Archives</a></td></tr><tr><td><strong>Mark as read</strong> / <strong>Mark as unread</strong></td><td>changes the read state</td></tr><tr><td><strong>Delete</strong></td><td>moves the mails to the Gmail trash</td></tr><tr><td><strong>Add a label</strong></td><td>applies an existing Gmail label (picked from a list)</td></tr><tr><td><strong>Create a rule</strong></td><td>opens the rule form, prefilled when the selection comes from a single sender</td></tr></tbody></table><p>On mobile, the bar sits at the bottom of the screen: four actions visible, the others under <strong>More</strong>.</p><hr><h2 id="undo" tabindex="-1">Undo <a class="header-anchor" href="#undo" aria-label="Permalink to &quot;Undo&quot;">​</a></h2><p><strong>Delete</strong> and <strong>Archive (remove from inbox)</strong> do not run right away: a toast shows for example &quot;Deleting 12 emails in 10 s&quot; (&quot;To the Gmail trash · tracked in Activity&quot;) with an <strong>Undo</strong> button. The mails leave the list immediately; <strong>Undo</strong> within 10 seconds brings them back and nothing is done. After the delay the action runs (&quot;Too late to undo: the action is already running.&quot; if you click too late).</p><p>During the delay, the task shows as &quot;Waiting&quot; in <a href="./activity.html">Activity</a>, where it can also be cancelled.</p><p>The other actions (read state, label, NAS backup) start immediately; their progress shows at the top of the list.</p><hr><h2 id="read-a-mail" tabindex="-1">Read a mail <a class="header-anchor" href="#read-a-mail" aria-label="Permalink to &quot;Read a mail&quot;">​</a></h2><p>Click a mail (or <strong>Open</strong>): the reader opens as a panel on the right (full screen on mobile).</p><ul><li>Header: subject, <strong>From</strong>, <strong>To</strong>, date, labels.</li><li>The mail body is shown in an isolated frame, without scripts. <strong>Remote images are blocked</strong> (&quot;Remote images blocked to protect your privacy.&quot;); <strong>Show</strong> loads them for that mail. To allow them everywhere, see <a href="./settings.html#account">Settings › Account</a>.</li><li>Downloadable attachments, and the <strong>Conversation</strong> (the other messages of the thread).</li><li>Actions: <strong>Archive (remove from inbox)</strong>, <strong>Save to the NAS</strong>, <strong>Delete</strong>, <strong>Create a rule</strong> (prefilled with the sender).</li></ul><hr><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><p>On desktop, under the list:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>j</code> / <code>k</code></td><td>next / previous mail</td></tr><tr><td><code>o</code></td><td>open the mail</td></tr><tr><td><code>e</code></td><td>archive (remove from inbox)</td></tr><tr><td><code>#</code></td><td>delete</td></tr><tr><td><code>r</code></td><td>mark as read</td></tr><tr><td><code>u</code></td><td>mark as unread</td></tr><tr><td><code>/</code></td><td>go to the search</td></tr><tr><td><code>Esc</code></td><td>clear the selection</td></tr></tbody></table><p><code>e</code>, <code>#</code>, <code>r</code> and <code>u</code> act on the selection, otherwise on the focused mail. Shortcuts are inactive while typing and while the reader or a form is open.</p><p>These are single-key shortcuts: the <strong>Turn off</strong> link under the list (or the <strong>Single-key keyboard shortcuts</strong> switch in <a href="./settings.html#account">Settings › Account</a>) disables them, for instance if you use voice control. The choice is remembered by the browser.</p>',46)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
